// Firestore rules generated by src/ops/firebaseRules.ts, on the emulator.
// Mirrors the join flow of src/data/firebase.ts (ensureUserRecord): admin
// first, then the invitation's role, then member when sign-up allows it.
import { assertFails, assertSucceeds, initializeTestEnvironment } from "@firebase/rules-unit-testing";
import { collection, deleteDoc, doc, getDoc, getDocs, setDoc, updateDoc } from "firebase/firestore";
import { ADMIN, buildFirestoreRules, FIRESTORE, PROJECT, summary, t } from "./rules.mjs";

// A users/{uid} record exactly as ensureUserRecord writes it.
const userRec = (uid, email, role, extra = {}) => ({ email, name: email.split("@")[0], authUid: uid, createdAt: Date.now(), updatedAt: Date.now(), role, ...extra });
const submission = (formId, extra = {}) => ({ formId, data: { email: "lead@example.com" }, createdAt: Date.now(), ...extra });

async function env(projectId, options) {
  const e = await initializeTestEnvironment({ projectId, firestore: { rules: buildFirestoreRules(options), ...FIRESTORE } });
  const as = (uid, email, verified = true, provider = "google.com") =>
    e.authenticatedContext(uid, { email, email_verified: verified, firebase: { sign_in_provider: provider } }).firestore();
  return { e, as, anon: e.unauthenticatedContext().firestore() };
}

// ─── Sign-up "invite" (default) ─────────────────────────────────────────
{
  const { e, as, anon } = await env(PROJECT, { adminEmail: ADMIN });
  const boss = as("boss", ADMIN);
  const bossUnverified = as("boss2", ADMIN, false, "password");
  const eve = as("eve", "eve@evil.test");
  const anna = as("anna", "anna@example.com");
  const annaUnverified = as("anna2", "anna@example.com", false, "password");
  const vic = as("vic", "vic@example.com");
  const pat = as("pat", "pat@example.com");

  await t("unverified bootstrap address cannot create the admin record", assertFails(setDoc(doc(bossUnverified, "users/boss2"), userRec("boss2", ADMIN, "admin"))));
  await t("bootstrap admin creates its admin record", assertSucceeds(setDoc(doc(boss, "users/boss"), userRec("boss", ADMIN, "admin"))));
  await t("admin creates the schema (objects)", assertSucceeds(setDoc(doc(boss, "objects/companies"), { labelPlural: "Companies" })));
  await t("admin creates a form", assertSucceeds(setDoc(doc(boss, "forms/contact"), { name: "Contact" })));
  await t("admin creates an automation", assertSucceeds(setDoc(doc(boss, "automations/a1"), { name: "Follow up", enabled: true })));
  await t("stranger cannot create a member record", assertFails(setDoc(doc(eve, "users/eve"), userRec("eve", "eve@evil.test", "member"))));
  await t("stranger cannot read records", assertFails(getDocs(collection(eve, "records"))));
  await t("stranger cannot invite itself", assertFails(setDoc(doc(eve, "invites/eve@evil.test"), { role: "member" })));
  await t("admin invites anna as member", assertSucceeds(setDoc(doc(boss, "invites/anna@example.com"), { role: "member", userId: "placeholder-anna" })));
  await t("admin invites vic as viewer", assertSucceeds(setDoc(doc(boss, "invites/vic@example.com"), { role: "viewer" })));
  await t("admin can't write an upper-case invite id", assertFails(setDoc(doc(boss, "invites/Pat@Example.com"), { role: "member" })));
  await t("admin can't invite with a bogus role", assertFails(setDoc(doc(boss, "invites/x@example.com"), { role: "owner" })));
  await t("stranger cannot read anna's invite", assertFails(getDoc(doc(eve, "invites/anna@example.com"))));
  await t("anna reads her own invite", assertSucceeds(getDoc(doc(anna, "invites/anna@example.com"))));
  await t("unverified anna (password) cannot join", assertFails(setDoc(doc(annaUnverified, "users/anna2"), userRec("anna2", "anna@example.com", "member", { replaces: "placeholder-anna" }))));
  await t("anna cannot join with a forged authUid", assertFails(setDoc(doc(anna, "users/anna"), userRec("other", "anna@example.com", "member", { replaces: "placeholder-anna" }))));
  await t("anna cannot take the admin role", assertFails(setDoc(doc(anna, "users/anna"), userRec("anna", "anna@example.com", "admin"))));
  await t("anna cannot replace another placeholder", assertFails(setDoc(doc(anna, "users/anna"), userRec("anna", "anna@example.com", "member", { replaces: "someone-else" }))));
  await t("anna joins with the invitation's role", assertSucceeds(setDoc(doc(anna, "users/anna"), userRec("anna", "anna@example.com", "member", { replaces: "placeholder-anna" }))));
  await t("member writes a record", assertSucceeds(setDoc(doc(anna, "records/r1"), { object: "companies", fields: { name: "Acme" } })));
  await t("member logs an activity", assertSucceeds(setDoc(doc(anna, "activities/n1"), { type: "note", title: "Hi", targets: [] })));
  await t("member cannot change the schema", assertFails(setDoc(doc(anna, "objects/companies"), { labelPlural: "Firms" })));
  await t("member cannot change settings", assertFails(setDoc(doc(anna, "settings/main"), { name: "x" })));
  await t("member cannot install an extension", assertFails(setDoc(doc(anna, "extensions/evil"), { enabled: true })));
  await t("member renames itself", assertSucceeds(updateDoc(doc(anna, "users/anna"), { name: "Anna", updatedAt: Date.now() })));
  await t("member cannot change its own role", assertFails(updateDoc(doc(anna, "users/anna"), { role: "admin" })));
  await t("member creates a private view", assertSucceeds(setDoc(doc(anna, "views/v1"), { object: "companies", ownerId: "anna", shared: false })));
  await t("member cannot create a shared view", assertFails(setDoc(doc(anna, "views/v2"), { object: "companies", ownerId: "anna", shared: true })));
  await t("member cannot take over the admin's view", assertFails(setDoc(doc(anna, "views/v3"), { object: "companies", ownerId: "boss", shared: false })));
  await t("member stamps lastRunAt on an automation", assertSucceeds(updateDoc(doc(anna, "automations/a1"), { lastRunAt: Date.now() })));
  await t("member cannot edit an automation", assertFails(updateDoc(doc(anna, "automations/a1"), { enabled: false })));
  await t("member logs an automation run", assertSucceeds(setDoc(doc(anna, "automationRuns/run1"), { automationId: "a1" })));
  await t("member uploads file metadata", assertSucceeds(setDoc(doc(anna, "files/f1"), { name: "a.pdf", size: 3 })));
  await t("member cannot purge file metadata", assertFails(deleteDoc(doc(anna, "files/f1"))));
  await t("admin purges file metadata", assertSucceeds(deleteDoc(doc(boss, "files/f1"))));
  await t("member cannot invite people", assertFails(setDoc(doc(anna, "invites/friend@example.com"), { role: "member" })));
  await t("member cannot list invitations", assertFails(getDocs(collection(anna, "invites"))));
  await t("vic joins as viewer", assertSucceeds(setDoc(doc(vic, "users/vic"), userRec("vic", "vic@example.com", "viewer"))));
  await t("viewer reads records", assertSucceeds(getDocs(collection(vic, "records"))));
  await t("viewer cannot write records", assertFails(setDoc(doc(vic, "records/r2"), { object: "companies", fields: {} })));
  await t("viewer cannot read the lead inbox", assertFails(getDocs(collection(vic, "inbox"))));
  await t("uninvited pat cannot join in invite mode", assertFails(setDoc(doc(pat, "users/pat"), userRec("pat", "pat@example.com", "member"))));

  // Public lead-form inbox.
  await t("anonymous visitor submits a lead form", assertSucceeds(setDoc(doc(anon, "inbox/s1"), submission("contact", { meta: { page: "https://example.com" } }))));
  await t("submission to an unknown form is refused", assertFails(setDoc(doc(anon, "inbox/s2"), submission("nope"))));
  await t("submission with an extra key is refused", assertFails(setDoc(doc(anon, "inbox/s3"), submission("contact", { role: "admin" }))));
  await t("submission with a stale createdAt is refused", assertFails(setDoc(doc(anon, "inbox/s4"), submission("contact", { createdAt: Date.now() - 3 * 86_400_000 }))));
  await t("submission with too many fields is refused", assertFails(setDoc(doc(anon, "inbox/s5"), { ...submission("contact"), data: Object.fromEntries(Array.from({ length: 61 }, (_, i) => [`f${i}`, "x"])) })));
  await t("anonymous visitor cannot read the inbox", assertFails(getDoc(doc(anon, "inbox/s1"))));
  await t("anonymous visitor cannot overwrite a submission", assertFails(setDoc(doc(anon, "inbox/s1"), submission("contact"))));
  await t("member reads the inbox", assertSucceeds(getDocs(collection(anna, "inbox"))));
  await t("member marks a failed submission", assertSucceeds(updateDoc(doc(anna, "inbox/s1"), { status: "error", error: "bad email" })));
  await t("member cannot rewrite a submission's data", assertFails(updateDoc(doc(anna, "inbox/s1"), { data: { email: "x@y.z" } })));
  await t("member deletes an ingested submission", assertSucceeds(deleteDoc(doc(anna, "inbox/s1"))));

  // Revocation and the closed default.
  await t("admin disables anna", assertSucceeds(updateDoc(doc(boss, "users/anna"), { disabled: true })));
  await t("disabled member loses read access", assertFails(getDocs(collection(anna, "records"))));
  await t("disabled member cannot re-enable itself", assertFails(updateDoc(doc(anna, "users/anna"), { disabled: false })));
  await t("unknown collections are closed, even to the admin", assertFails(setDoc(doc(boss, "secrets/x"), { a: 1 })));
  await t("stranger still locked out after all this", assertFails(getDoc(doc(eve, "records/r1"))));
  await e.cleanup();
}

// ─── Sign-up "open": anyone verified joins as member, never more ────────
{
  const { e, as } = await env(`${PROJECT}-open`, { adminEmail: ADMIN, signup: "open" });
  const eve = as("eve", "eve@evil.test");
  await t("[open] stranger cannot join as admin", assertFails(setDoc(doc(eve, "users/eve"), userRec("eve", "eve@evil.test", "admin"))));
  await t("[open] stranger joins as member", assertSucceeds(setDoc(doc(eve, "users/eve"), userRec("eve", "eve@evil.test", "member"))));
  await t("[open] unverified password account cannot join", assertFails(setDoc(doc(as("p", "p@example.com", false, "password"), "users/p"), userRec("p", "p@example.com", "member"))));
  await e.cleanup();
}

// ─── Sign-up "domain": verified addresses of the listed domains ─────────
{
  const { e, as } = await env(`${PROJECT}-domain`, { adminEmail: ADMIN, signup: "domain", allowedDomains: ["acme.io"] });
  await t("[domain] acme.io address joins as member", assertSucceeds(setDoc(doc(as("a", "ann@acme.io"), "users/a"), userRec("a", "ann@acme.io", "member"))));
  await t("[domain] look-alike domain refused", assertFails(setDoc(doc(as("b", "bob@acme.io.evil.test"), "users/b"), userRec("b", "bob@acme.io.evil.test", "member"))));
  await t("[domain] other domain refused", assertFails(setDoc(doc(as("c", "cat@other.org"), "users/c"), userRec("c", "cat@other.org", "member"))));
  await e.cleanup();
}

process.exit(summary("Firestore rules") ? 1 : 0);
